import re
import pathlib

root = pathlib.Path("components/ui")

for f in sorted(root.glob("*.py")):
    text = f.read_text()
    lines = text.split("\n")

    needs_component = bool(re.search(r'(?<!rx\.)\bComponent\b', text)) and ": Component" in text
    # more precise: does file use bare "Component" as an annotation (not rx.Component, not ComponentNamespace)?
    needs_component = bool(re.search(r'[^.\w]Component\b(?!Namespace)', text))
    has_component_import = bool(re.search(r'^from reflex(_base)?\.components\.component import.*\bComponent\b(?!Namespace)', text, re.M))
    # check each import line for Component as a standalone name
    has_component_import = False
    for line in lines:
        m = re.match(r'^from reflex(?:_base)?\.components\.component import (.+)$', line)
        if m:
            names = [n.strip() for n in m.group(1).split(",")]
            if "Component" in names:
                has_component_import = True

    needs_any = ": Any" in text
    has_any_import = False
    typing_import_idx = None
    for i, line in enumerate(lines):
        m = re.match(r'^from typing import (.+)$', line)
        if m:
            typing_import_idx = i
            names = [n.strip() for n in m.group(1).split(",")]
            if "Any" in names:
                has_any_import = True

    changed = False

    if needs_component and not has_component_import:
        # find existing component import line to extend, else add new line
        comp_import_idx = None
        for i, line in enumerate(lines):
            m = re.match(r'^from reflex\.components\.component import (.+)$', line)
            if m:
                comp_import_idx = i
                names = [n.strip() for n in m.group(1).split(",")]
                break
        if comp_import_idx is not None:
            names = sorted(set(names + ["Component"]))
            lines[comp_import_idx] = f"from reflex.components.component import {', '.join(names)}"
        else:
            # insert after "import reflex as rx" line or after typing import, else at top
            insert_idx = 0
            for i, line in enumerate(lines):
                if line.startswith("import reflex as rx") or line.startswith("from reflex"):
                    insert_idx = i + 1
            if insert_idx == 0:
                for i, line in enumerate(lines):
                    if line.startswith("from typing import"):
                        insert_idx = i + 1
            lines.insert(insert_idx, "from reflex.components.component import Component")
        changed = True

    if needs_any and not has_any_import:
        if typing_import_idx is not None:
            m = re.match(r'^from typing import (.+)$', lines[typing_import_idx])
            names = [n.strip() for n in m.group(1).split(",")]
            names = sorted(set(names + ["Any"]))
            lines[typing_import_idx] = f"from typing import {', '.join(names)}"
        else:
            lines.insert(0, "from typing import Any")
        changed = True

    if changed:
        f.write_text("\n".join(lines))
        print(f"fixed imports: {f.name}")
